import{_ as o,l as r,o as e,c as l,v as t,p as s,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"透镜加热与补偿","description":"","frontmatter":{"title":"透镜加热与补偿","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/lens-heating-compensation.md","filePath":"litho/lens-heating-compensation.md","lastUpdated":1789023840000}'),c={name:"litho/lens-heating-compensation.md"};function _(m,a,u,A,E,f){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="透镜加热与补偿" tabindex="-1">透镜加热与补偿 <a class="header-anchor" href="#透镜加热与补偿" aria-label="Permalink to &quot;透镜加热与补偿&quot;">​</a></h1><div class="epigraph"><p>玻璃吃掉的那一小截 193 nm 变成热。折射率与面形随温度场变，像差跟着扫描历史走，不是一场一个常数。</p><footer>—— 对照投影物镜 lens heating 补偿的公开描述；[Zernike](/litho/zernike-aberrations)</footer></div><p><a href="/litho/catadioptric-lens-design">上一课</a>给出冷态设计。缺口是运行：吸收 → 温度场 → \\(n(T)\\) 与面形 → 波前。本课钉加热与补偿，不重写 Zernike 定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>透过率不是 100%。狭缝里的功率密度随光瞳与掩模透过率变，热场是「这场图形」的函数。刚开机与连扫一小时的像差不同。把套刻/CD 漂移全写成工件台，会漏掉镜头热时间常数（秒到十分钟）。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型：若干 Zernike 的加热系数 × 估计功率（剂量、光瞳、掩模开放率）。执行器：后课操纵器、调焦、波长微调。生产：idle 曝光或补偿表随 lot 更新。换高透过掩模等于换热负载。</p>',7)),(e(),s(p,null,{default:i(()=>[h(n,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABS%5B%22%E7%8E%BB%E7%92%83%E5%90%B8%E6%94%B6%22%5D%20--%3E%20T%5B%22%E6%B8%A9%E5%BA%A6%E5%9C%BA%22%5D%0A%20%20T%20--%3E%20W%5B%22%E6%B3%A2%E5%89%8D%20%2F%20Zernike%22%5D%0A%20%20W%20--%3E%20CMP%5B%22%E8%A1%A5%E5%81%BF%E8%A1%A8%20%2B%20%E6%93%8D%E7%BA%B5%E5%99%A8%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">补偿是前馈为主：用即将曝光的场预测热，而不是等 CD 坏了再反馈。传感器在镜头里有限，模型误差会变成系统残差。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(dn/dT\\) 与热膨胀改光程。非均匀热场激发球差、像散等轴对称或扫描向模态。时间上像一个低通：脉冲级看不見，场间与 lot 间看见。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课操纵器是执行器细节。致密化（compaction）是剂量积分的永久损伤，不是可逆加热，再后一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>镜头热像差随图形与历史变，要前馈补偿。</li><li>时间常数在场–lot 之间，不在单个脉冲。</li><li>出处：lens heating 公开实践；Zernike 课。</li></ul>',7))])}const k=o(c,[["render",_]]);export{T as __pageData,k as default};
